/* The shape of a hand as it is: mimic_row with a spare tile added and
 * discarded, without the discard's kind and seen copies. */
static void hand_shape(const int *c, int *av, int opened, double *f) {
    int k[NTILES], x = -1;
    for (int t = 0; t < 27 && x < 0; t++)
        if (c[t] == 0 && av[t] > 0) x = t;
    for (int t = 0; t < 33 && x < 0; t++)
        if (c[t] < 4) x = t;
    memcpy(k, c, sizeof k);
    k[x]++;
    mimic_row(k, av, opened, x, f);
    f[11] = f[12] = f[13] = f[14] = 0.0;
}

